  const sample=async(operation:string,run:()=>Promise<unknown>)=>{
   stage=operation;const samples:Sample[]=[]
   for(let i=0;i<4;i++){
    const s:Sample={phase:i===0?'warmup':'measured',sample:i,transactions:0,sqlQueries:0,stateReads:0,corporateReads:0,sqlMs:0,totalMs:0,bytes:0,bodySha256:'',status:null,headers:[]}
    active=s;const start=performance.now()
    try{const encoded=await encode(await run());s.totalMs=performance.now()-start;s.bytes=encoded.bytes.byteLength;s.bodySha256=hash(encoded.bytes);s.status=encoded.status;s.headers=encoded.headers;check(s.status===null||s.status===200,'Native route failed');samples.push(s)}finally{active=null}
   }
   const expected=samples[0]!
   check(samples.every(s=>s.bodySha256===expected.bodySha256&&s.bytes===expected.bytes&&s.status===expected.status&&same(s.headers,expected.headers)),'Responses differ across samples')
   const times=samples.slice(1).map(s=>s.totalMs).sort((a,b)=>a-b)
   cases.push({operation,samples,medianMs:times[1]!,maxMs:times[2]!})
   console.log(JSON.stringify({operation,samples:3,medianMs:times[1],sqlQueries:expected.sqlQueries,stateReads:expected.stateReads}))
  }
  await sample('direct_register',()=>db.findScope1(actor,COMPANY,authorities,policy))
  await sample('direct_version',()=>db.findScope1Version(actor,COMPANY,version.streamId,version.id,authorities,policy))
  await sample('direct_report',()=>db.findScope1Report(actor,COMPANY,report.streamId,report.id,authorities,policy))
  const paths=[['register','scope1-inventory'],['version',`scope1-inventory/${version.streamId}/versions/${version.id}`],['version_export',`scope1-inventory/${version.streamId}/versions/${version.id}/inventory-export`],['version_proof',`scope1-inventory/${version.streamId}/versions/${version.id}/proof`],['report',`scope1-inventory/${report.streamId}/reports/${report.id}`],['report_download',`scope1-inventory/${report.streamId}/reports/${report.id}/download`],['report_snapshot',`scope1-inventory/${report.streamId}/reports/${report.id}/snapshot`],['report_proof',`scope1-inventory/${report.streamId}/reports/${report.id}/proof`]] as const
  for(const [label,factory] of [['before',beforeFactory],['after',afterFactory]] as const){
   const route=factory({database:db as M78RouteDatabase,authorities,policy,origin:ORIGIN,validateUser:async()=>({id:actor,email:null,phone:null,fullName:null})})
   for(const [name,path] of paths)await sample(label+'_'+name,()=>route(new Request(`${ORIGIN}/workspace/${COMPANY}/${path}`,{method:'GET',headers:{authorization:'Bearer local-comparison'}})))
  }
  stage='comparison'
  for(const [name] of paths){const a=cases.find(c=>c.operation==='before_'+name)!,b=cases.find(c=>c.operation==='after_'+name)!;check(a.samples.every(s=>s.bodySha256===b.samples[0]!.bodySha256&&s.status===b.samples[0]!.status&&same(s.headers,b.samples[0]!.headers)),'Before/after response changed: '+name);check(b.samples.every(s=>s.stateReads===1),'Candidate duplicate state read: '+name);if(name!=='register')check(a.samples.every(s=>s.stateReads===2)&&b.samples.every(s=>s.sqlQueries<a.samples[0]!.sqlQueries),'No structural reduction: '+name)}
  afterDigest=await digests(admin);check(same(beforeDigest,afterDigest),'Base-table data changed');await verify()
  const result={status:'m78_get_route_local_comparison_passed',createdAt:new Date().toISOString(),admissionSha256:hash(admissionBytes),historicalSourceInventorySha256:hash(historicalBytes),sourcesVerifiedBeforeAndAfter:true,historicalSources:173,extraPins:admission.extraPins,beforeRouteSha256:admission.beforeRouteSha256,afterRouteSha256:admission.afterRouteSha256,database:DATABASE,companyId:COMPANY,reportId:report.id,versionId:version.id,hostCalls:0,applicationWrites:0,httpPostRequests:0,tableDigestsBefore:beforeDigest,tableDigestsAfter:afterDigest,digestScope:'121 neuvetra base-table row sets; no sequence/settings/external-effect claim',warmupsPerCase:1,measuredSamplesPerCase:3,cases,noHostedTimingOrSlaClaim:true}
  await writeFile(OUT,JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({status:result.status,cases:cases.length,dataPreserved:true}))
